<script setup lang="ts">
import{ref,watch,onBeforeUnmount}from'vue';import{v1}from'../api';
const props=defineProps<{runId:string}>();const rows=ref<Array<{id:string;state:string;summary:string;tokensBefore:number|null;tokensAfter:number|null;createdAt:string}>>([]),error=ref(''),loading=ref(false);let c:AbortController|undefined;
async function load(){c?.abort();const next=new AbortController();c=next;error.value='';rows.value=[];loading.value=true;try{const data=await v1<{checkpoints:typeof rows.value}>(`/api/v1/runs/${props.runId}/context-history`,{signal:next.signal});if(!next.signal.aborted)rows.value=data.checkpoints;}catch(e){if(!next.signal.aborted)error.value=String(e);}finally{if(!next.signal.aborted)loading.value=false;}}
watch(()=>props.runId,load,{immediate:true});onBeforeUnmount(()=>c?.abort());
</script>
<template><section class="context-history" aria-label="压缩历史"><header><h3>上下文整理历史</h3><button class="text-btn" @click="load">刷新</button></header><p v-if="error" role="alert">{{error}}</p><p v-if="loading" role="status">正在读取整理历史…</p><p v-else-if="!rows.length && !error" class="muted">此会话尚无上下文整理记录。</p><details v-for="row in rows" :key="row.id"><summary><span>{{row.state==='confirmed'?'已确认':row.state==='rejected'?'未采用':row.state==='superseded'?'已替代':'处理中'}}</span><time>{{new Date(row.createdAt).toLocaleString('zh-CN')}}</time><small>{{row.tokensBefore??'—'}} → {{row.tokensAfter??'—'}} Token</small></summary><pre>{{row.summary}}</pre></details></section></template>
<style scoped>.context-history{padding:16px;border:1px solid var(--border);border-radius:12px;background:var(--bg-panel)}header{display:flex;justify-content:space-between;align-items:center}h3{font-size:14px;margin:0}details{border-top:1px solid var(--border);padding:12px 0}summary{display:flex;gap:12px;flex-wrap:wrap;cursor:pointer;font-size:12px}time,small{color:var(--fg-subtle)}pre{font:12px/1.65 var(--font-ui);white-space:pre-wrap;overflow-wrap:anywhere}[role=alert]{color:var(--danger)}</style>
